async function aJW(pk:string,tid:string,kid:string):Promise<string>{const pem=pk.replace("-----BEGIN PRIVATE KEY-----","").replace("-----END PRIVATE KEY-----","").replace(/\s/g,"");const bin=Uint8Array.from(atob(pem),c=>c.charCodeAt(0));const key=await crypto.subtle.importKey("pkcs8",bin,{name:"ECDSA",namedCurve:"P-256"},false,["sign"]);const h={alg:"ES256",kid};const ns=Math.floor(Date.now()/1000);const pl={iss:tid,iat:ns,exp:ns+3600};const enc=new TextEncoder();const b64u=(s:string)=>s.replace(/=/g,"").replace(/\+/g,"-").replace(/\//g,"_");const hb=b64u(btoa(JSON.stringify(h))),pb=b64u(btoa(JSON.stringify(pl))),si=hb+"."+pb;const sig=await crypto.subtle.sign({name:"ECDSA",hash:"SHA-256"},key,enc.encode(si));const sb=b64u(btoa(String.fromCharCode(...new Uint8Array(sig))));return si+"."+sb;}
