const CSE:any={off:0,standard:6,strong:10};const CSC2:any={off:0,standard:18,strong:30};
function csB(sc:number,mo="standard",w=1.0):number{if(sc<=1)return 0;return rd4(Math.min(CSC2[mo]??18,(sc-1)*(CSE[mo]??6))*w);}
