function cAG2(tracks:any[],mp=3,op=8):any[]{if(tracks.length===0)return[];const g=new Map<string,any[]>();for(const t of tracks){const k=t.lak||"__u__";if(!g.has(k))g.set(k,[]);g.get(k)!.push(t);}const rm=new Map<string,any>();for(const[,gr]of g){if(gr.length<=mp){for(const t of gr)rm.set(t.nk,{nk:t.nk,pen:0,ovf:false,idx:0});continue;}const s=[...gr].sort((a,b)=>b.pt-a.pt);for(let i=0;i<s.length;i++){if(i<mp)rm.set(s[i].nk,{nk:s[i].nk,pen:0,ovf:false,idx:0});else{const oi=i-mp+1;rm.set(s[i].nk,{nk:s[i].nk,pen:rd4(oi*op),ovf:true,idx:oi});}}}return tracks.map(t=>rm.get(t.nk)??{nk:t.nk,pen:0,ovf:false,idx:0});}
