const RATE_LIMIT_MAX=300;const RATE_LIMIT_WINDOW_SECONDS=60;
async function ckRL(db:any,key:string):Promise<{allowed:boolean;remaining:number;resetAt:string}>{
  const ws=new Date(Date.now()-RATE_LIMIT_WINDOW_SECONDS*1000).toISOString();
  try{
    const{count,error}=await db.from("rate_limit_log").select("*",{count:"exact",head:true}).eq("bucket_key",key).gte("created_at",ws);
    if(error)return{allowed:true,remaining:RATE_LIMIT_MAX,resetAt:""};
    const c=count??0;const rem=Math.max(0,RATE_LIMIT_MAX-c-1);
    const ra=new Date(Date.now()+RATE_LIMIT_WINDOW_SECONDS*1000).toISOString();
    db.from("rate_limit_log").insert({bucket_key:key,created_at:is()}).then(()=>{/* fire and forget */});
    return{allowed:c<RATE_LIMIT_MAX,remaining:rem,resetAt:ra};
  }catch{return{allowed:true,remaining:RATE_LIMIT_MAX,resetAt:""};}
}

